from 写入第二遍 import add
add('12_003',1,'16:9，青头肩与后拉拳的斜侧近景，脸居画面右侧，拳头拉在左后深层；镜头贴着她肩线短移，停在拳、耳尖和圆眼同框处。','青把刚握紧的拳向后抽，肩胛带着上身拧开，拳和胸口拉出一条紧绷斜线；她圆睁双眼锁住武士侧头，嘴唇轻合，另一肩先向前顶，后拉的拳在镜尾骤然离开蓄力位置。发根被转肩带起，长马尾随后向左后掀开。','人物外侧为深蓝灰放射图形底，浅冷白细线从拳后方向脸侧快速收束，边缘一小条灰绿石铺地面随短移擦过。','人物保持云天冷白柔光，拳背亮面短促滑过，图形底加深形成蓄力对比。','护腕骤绷声，肩背拧开的一记短布擦，拳启动时风声变尖。',phase='preparation',node={'叙事阶段':'青背后拉拳结束，即将命中'},meaning='青圆眼专注、拳后拉与转肩蓄力保留，下一镜进入同一拳的接触。',motion='肩与拳先向左后拉开，再向画面右前同一目标送出。',ground='腿部在画外维持后侧立足，起力从支撑侧向肩传递。',characters=['青'])
add('12_004',1.5,'16:9，拳击接触的极近景，武士白眼和椭圆头部占画面左下，青拳与前臂由右下斜入头／颈侧；固定机位，命中点居中央偏右。','青的拳从后拉位置爆发前送，拳面压进武士侧头与颈根的交叠处；厚重轮廓被顶成短弧，白眼猛张，黑隙向下扯长。拳面停住极短一拍，随后受力弧线弹开，武士的头先向侧面甩走，肩部被带出画幅；闷哼被这一击挤出。','极近主体之外仅余浅冷灰白图形底场，细长冲击线从接触点向左下放射。','同场冷白光在接触形上短促提高对比，外围归回浅冷灰，亮度随接触消退。','一记紧实沉闷拳响，接厚重身体被推出的短风；闷哼在台词栏发声。',ja=['ぐっ…！！'],tone='武士挨拳被挤出的一声短闷哼，起音受阻，随甩头迅速截住。',kind='mixed',phase='contact',node={'叙事阶段':'青一拳命中头颈侧，武士被推出原位','武士.位置':'受击开始离地横移'},meaning='拳击头／颈侧的挤压形、睁大的白眼与武士闷哼保留。',motion='拳由右下斜向左上顶入，头肩沿受力侧被甩出画幅。',ground='命中后武士重心被带出支撑，接下一镜全身离地。',characters=['青','鬼头武士'])
add('13_001',1.5,'16:9，侧方远景，平台斜穿画面下方，武士巨大身体在中央偏右、青贴其右下侧；镜头随两人向右横移，落幅仍留左侧起点烟尘和两人完整轮廓。','武士的头肩沿拳力向右甩出，脚底离地，双臂在惯性里拉开；青向前蹬出一步紧跟在其胸侧，收回的拳护住面前，另一肩已向下一击转入。白色宽冲击带从左上沿武士背后拖过，左侧米灰尘团向外翻，青没有被巨体甩远。','灰绿石铺平台沿下缘斜过，左后米灰尘团占一角，上方浅蓝灰云天铺开。','上方云天冷白漫射，武士与青的轮廓保持清晰，尘团外缘较亮、内侧偏暖灰。','重拳余声转成厚重破风，青鞋底最后一次蹬石短响，碎屑落回起点。',phase='result',node={'叙事阶段':'武士横向离地，青贴身跟进','青.位置':'武士胸侧近身','武士.位置':'平台上方横飞'},meaning='被击离地的巨大武士与贴身跟进的青同框，建立后续连续拳击的距离。',motion='武士与青同向向右，镜头平行追移，青保持约一臂内的贴身距离。',ground='武士双脚离地；青由一次蹬石转入短暂悬空跟进。',characters=['青','鬼头武士'])
